SELECT *, LAST_VALUE(browser) IGNORE NULLS OVER (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_browser, FIRST_VALUE(country, TRUE) OVER (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_country, ROW_NUMBER() OVER (PARTITION BY browser, customer_id ORDER BY started_at DESC, id) AS seq_no FROM sessions;
